WITH flattened AS (SELECT id, service, host, log_ts, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) e AS attr_key, v), with_gaps AS (SELECT *, CASE WHEN log_ts - LAG(log_ts) OVER (PARTITION BY service ORDER BY log_ts ASC, id ASC, attr_key ASC) > INTERVAL '1' HOUR THEN 1 ELSE 0 END AS new_group_flag FROM flattened), islands AS (SELECT id, service, host, log_ts, status_code, attr_key, v, SUM(new_group_flag) OVER (PARTITION BY service ORDER BY log_ts ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY log_ts DESC, id ASC, attr_key ASC) AS latest_rank FROM islands) t WHERE latest_rank = 1), scored AS (SELECT id, host, attr_key, v, COUNT(status_code) OVER (PARTITION BY attr_key ORDER BY session_id ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_status_code, AVG(status_code) OVER (PARTITION BY attr_key ORDER BY session_id ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_status_code, MAX(status_code) OVER (PARTITION BY attr_key ORDER BY session_id ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_status_code FROM ranked), valid AS (SELECT *, running_max_status_code - running_count_status_code AS running_max_status_code_minus_running_count_status_code, CAST(running_max_status_code AS INT) AS running_max_status_code_int FROM scored WHERE attr_key IS NOT NULL AND attr_key IS DISTINCT FROM 'version'), ranked_app_logs AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY running_max_status_code_int ASC, id ASC, attr_key ASC) AS latest_rank FROM valid QUALIFY latest_rank = 1) SELECT id, host, attr_key, v, running_count_status_code, running_avg_status_code, running_max_status_code_int, latest_rank, CASE WHEN attr_key RLIKE '^(trace|version)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS attr_key_zone FROM ranked_app_logs ORDER BY running_count_status_code ASC, id ASC;
